import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';

/**
 * Bencho UI sounds. Files are git-ignored (docs/SPEC.md §6.4), so the
 * registry is generated by `npm run bencho:sounds` and metro.config.js
 * resolves it to an empty module when it hasn't been generated yet —
 * the app then runs silently instead of failing to bundle.
 */
// eslint-disable-next-line @typescript-eslint/no-require-imports
const generated = require('./registry.generated') as { SOUND_FILES?: Record<string, number> } | null;
const FILES: Record<string, number> = generated?.SOUND_FILES ?? {};

let enabled = true;
let ready = false;
const players = new Map<string, AudioPlayer>();

export function setSoundsEnabled(on: boolean): void {
  enabled = on;
}

export function availableSounds(): string[] {
  return Object.keys(FILES);
}

/** Call once at startup: audio session + one preloaded player per sound */
export async function initSounds(): Promise<void> {
  if (ready) return;
  ready = true;
  try {
    // UI sounds respect the mute switch and never stop the user's music
    await setAudioModeAsync({ playsInSilentMode: false, interruptionMode: 'mixWithOthers' });
  } catch {
    /* web, or a platform without an audio session */
  }
  for (const [id, source] of Object.entries(FILES)) {
    try {
      const p = createAudioPlayer(source);
      p.volume = 0.6;
      players.set(id, p);
    } catch {
      /* a missing or unreadable file stays silent */
    }
  }
}

export function playSound(id: string): void {
  if (!enabled) return;
  const p = players.get(id);
  if (!p) return;
  try {
    void p.seekTo(0);
    p.play();
  } catch {
    /* never let a sound break an interaction */
  }
}
